'use strict';
// 0.4: transport-led city services, schools, retained asset maintenance and train motion.
const SCHOOL_COST=3800;
const fresh03=fresh;fresh=function(){let x=fresh03();x.economyVersion=6;x.maintenance={accrued:0,debt:0,lastDay:0,lastSettledMonth:0,months:[]};x.ledger.maintenance=0;x.ledger.education=0;return x;};
save=function(){try{localStorage.setItem('transit-atlas-v1',JSON.stringify(S));}catch{}};
load=function(){try{let x=JSON.parse(localStorage.getItem('transit-atlas-v1')||localStorage.getItem('transit-atlas-city-beta-v4'));if(x?.version===1&&x.economyVersion===6){if(x.stockPathRevision!==4){try{if(!localStorage.getItem('transit-atlas-before-stock-v4'))localStorage.setItem('transit-atlas-before-stock-v4',JSON.stringify(x));}catch{}x.stockPathRevision=4;}if(x.moneyScale!==10){try{if(!localStorage.getItem('transit-atlas-before-1.1'))localStorage.setItem('transit-atlas-before-1.1',JSON.stringify(x));}catch{}migrateEconomy11(x);}S=x;S.paused=true;return true;}}catch{}return false;};
function cityService(c){return c.service??={records:[],samples:[],rating:'待评价',score:null,badDays:0,goodDays:0,protectUntil:Math.max(S.day,c.activatedDay||0)+14,peak:c.size,reason:'积累至少6位乘客的出行样本后评价'};}
const make03=makeCity;makeCity=function(...args){let c=make03(...args);cityService(c);return c;};
const freshPassenger03=newPassenger;newPassenger=function(c){let n=c.q.length;freshPassenger03(c);if(c.q.length>n)registerServicePassenger(c.q.at(-1));};
function registerServicePassenger(p){let c=S.cities[p.origin];if(!c||c.kind==='bridgehead')return;let svc=cityService(c);svc.records.push({id:p.id,day:S.day,done:false,wait:0});}
const match03=matchesDestination;matchesDestination=function(c,p){return p.schoolId!==undefined?!c.dormant&&c.id!==p.origin&&c.id===p.dest:match03(c,p);};
const label03=passengerLabel;passengerLabel=function(p){return p.schoolId!==undefined?'▤ '+(p.schoolReturn?'放学 → ':'上学 → ')+escapeHTML(S.cities[p.dest]?.name||'学校'):label03(p);};
const trip03=completeTrip;completeTrip=function(p,dest){trip03(p,dest);let c=S.cities[p.origin],rec=c&&cityService(c).records.find(r=>r.id===p.id);if(rec){rec.done=true;rec.wait=p.wait;rec.completed=S.day;}if(p.schoolId!==undefined&&!p.schoolReturn){let host=S.cities[p.schoolId];if(host?.school){if(p.schoolMonth===Math.floor(S.day/30)){host.school.monthArrived++;if(p.wait<=90*(S.cities[p.origin]?.shape===1?1.25:1))host.school.monthGood++;}host.school.returns.push({home:p.origin,at:S.day+.5});}}};
function schoolActive(c){return !!c.school&&c.size>=1&&!c.dormant;}
function schoolSources(c){return realCities().filter(s=>!s.dormant&&s.id!==c.id).sort((a,b)=>Math.hypot(a.x-c.x,a.y-c.y)-Math.hypot(b.x-c.x,b.y-c.y)).slice(0,3);}
function schoolPassenger(origin,dest,schoolId,schoolReturn=false){let d=S.cities[dest],p={id:S.nextP++,origin,dest,schoolId,schoolReturn,schoolMonth:Math.floor(S.day/30),color:d.color,shape:d.shape,wait:0,ready:0,journey:0,legs:{}};S.cities[origin].q.push(p);registerServicePassenger(p);return p;}
function updateSchools(){for(let c of realCities()){let s=c.school;if(!s)continue;let future=[];for(let r of s.returns){if(S.day>=r.at)schoolPassenger(c.id,r.home,c.id,true);else future.push(r);}s.returns=future;if(!schoolActive(c))continue;let day=Math.floor(S.day);if(day%7<5&&S.day-day>=.2&&s.lastDay!==day){s.lastDay=day;let sources=schoolSources(c);for(let source of sources){schoolPassenger(source.id,c.id,c.id);s.monthSpawned++;}}}}
function buildSchool(id){let c=S.cities[id];if(!c||c.dormant||c.kind==='bridgehead'||c.size<1||c.school)return toast('中型及大型城市每城可建一所学校');openModal(`<div class="modal-head"><h2>${escapeHTML(c.name)} · 建设学校</h2><button class="close" onclick="closeModal()">×</button></div><p>建设费 ¥${SCHOOL_COST}。每个工作日从最近的最多3座已接入城市各产生1位学生；实际送达后半个游戏日产生返程需求。书本标记指定城市。</p><p>学生正常支付票款。月底教育补贴＝基础额度×到校率×候车合格率×城市服务系数；小城基础1200，大城市1800。按本月建校天数折算，无学生到校则无补贴。降为小镇后暂停招生和补贴，保留校舍。</p><button class="primary" onclick="confirmSchool(${id})" ${S.points<SCHOOL_COST?'disabled':''}>支付 ¥${SCHOOL_COST} 建校</button>`);}
function confirmSchool(id){let c=S.cities[id];if(!c||c.dormant||c.kind==='bridgehead'||c.size<1||c.school||S.points<SCHOOL_COST)return;spend(SCHOOL_COST,'construction',c.name+'建设学校');c.school={built:S.day,lastDay:Math.floor(S.day),monthSpawned:0,monthArrived:0,monthGood:0,returns:[],lastSubsidy:0};cityService(c).protectUntil=Math.max(cityService(c).protectUntil,S.day+7);save();closeModal();openCity(id);toast('学校建成 · 请安排学生通勤');}
function evaluateCity(c,day){let svc=cityService(c);svc.peak=Math.max(svc.peak,c.size);svc.records=svc.records.filter(r=>r.day>=day-14);let pending=typeof pendingRatingPassengers==='function'?pendingRatingPassengers(c.id):(()=>{let pending=[];for(let city of realCities())for(let p of city.q)if(p.origin===c.id&&!p.eventId)pending.push(p);for(let v of S.vehicles)for(let p of v.people)if(p.origin===c.id&&!p.eventId)pending.push(p);return pending;})();let mature=svc.records.filter(r=>r.day<=day-1),done=mature.filter(r=>r.done),rate=mature.length?done.length/mature.length:1,waits=[...done.map(r=>r.wait/(c.shape===1?1.25:1)),...pending.map(p=>p.wait/(c.shape===1?1.25:1))],avg=waits.length?waits.reduce((a,b)=>a+b,0)/waits.length:0;
svc.samples.push({day,congested:c.q.filter(p=>!p.cardId).length>capacity(c)});svc.samples=svc.samples.filter(r=>r.day>day-14);let congestion=svc.samples.filter(r=>r.congested).length/Math.max(1,svc.samples.length);svc.delivery=rate;svc.wait=avg;svc.congestion=congestion;svc.count=mature.length;let enough=mature.length>=6;
let score=100*(.5*rate+.3*Math.max(0,1-avg/180)+.2*(1-congestion));if(enough&&rate<.35)score=Math.min(score,49);score=Math.max(0,Math.min(100,score+(svc.activityEffect?svc.activityEffect.amount*Math.max(0,Math.min(1,(svc.activityEffect.until-day)/14)):0)));svc.score=enough?Math.round(score):null;svc.rating=!enough?'待评价':score>=85?'优':score>=70?'良':score>=50?'一般':'差';svc.reason=!enough?'样本不足6人，暂不处罚':rate<.55?'送达率偏低，检查目的地连通和车辆停靠':avg>90?'候车时间较长，建议加车或优化换乘':congestion>.4?'长期拥挤，建议分流客流或建设枢纽':'服务稳定';
if(day<svc.protectUntil||!enough||c.dormant){svc.badDays=0;svc.goodDays=0;return;}if(svc.rating==='差'){svc.badDays++;svc.goodDays=0;if(svc.badDays===15)toast(c.name+'衰退预警：'+svc.reason+'，再持续15天将降级');if(svc.badDays>=30&&c.size>0){c.size--;c.capacity=[24,40,64][c.size];c.stage=c.size;svc.badDays=0;svc.protectUntil=day+15;toast(c.name+'长期服务差评，降为'+LEVELS[c.size]+'；改善后可恢复');}}else{svc.badDays=0;svc.goodDays=(svc.rating==='优'||svc.rating==='良')?svc.goodDays+1:0;if(svc.goodDays>=15&&c.size<svc.peak){c.size++;c.capacity=[24,40,64][c.size];svc.goodDays=0;svc.protectUntil=day+7;toast(c.name+'服务改善，恢复为'+LEVELS[c.size]+'（不重复发成长奖金）');}}}
const finish03=finishMission;finishMission=function(c){let old=c.size;finish03(c);let svc=cityService(c);svc.peak=Math.max(svc.peak,c.size);if(c.size>old)svc.protectUntil=Math.max(svc.protectUntil,S.day+7);};
function maintenanceAssets(){let items=[];for(let [k,x] of Object.entries(S.infrastructure)){if(x.type==='air')continue;let a=S.cities[x.a],b=S.cities[x.b];if(!a||!b||a.removed||b.removed||bridgeFor(a,b))continue;let len=Math.hypot(a.x-b.x,a.y-b.y),t=x.type==='track'?'emu':'bus',tunnels=requirements(a,b,t).tunnel||0,monthly=len*(x.type==='track'?(x.level>=2?.065:.045):.025)*(1+x.level*.12)+tunnels*5;items.push({key:k,label:a.name+' ↔ '+b.name,monthly:10*Math.round(monthly*100)/100});}for(let b of S.bridges){if(b.status==='removed')continue;let a=S.cities[b.heads[0]],z=S.cities[b.heads[1]],monthly=(6+Math.hypot(a.x-z.x,a.y-z.y)*.03)*(1+b.level*.15);items.push({key:'bridge-'+b.id,label:'桥梁 #'+b.id,monthly:10*Math.round(monthly*100)/100});}return items;}
function maintenanceForecast(){return S.maintenance.accrued+maintenanceAssets().reduce((n,a)=>n+a.monthly,0)*((30-S.day%30)/30);}
function payMaintenanceDebt(){let m=S.maintenance,paid=Math.min(S.points,m.debt);paid=Math.floor(paid*100)/100;if(paid>0){spend(paid,'maintenance','道路维护费');m.debt=Math.max(0,Math.round((m.debt-paid)*100)/100);}return paid;}
const credit03=credit;credit=function(amount,category,label){credit03(amount,category,label);if(S.maintenance?.debt>0)payMaintenanceDebt();};
function settleMonth(boundary){let m=S.maintenance;if((m.lastSettledMonth||0)>=boundary/30)return;m.lastSettledMonth=boundary/30;let bill=Math.round(m.accrued*100)/100;m.debt=Math.round((m.debt+bill)*100)/100;let paid=payMaintenanceDebt(),education=0;for(let c of realCities()){let school=c.school;if(!school)continue;let spawned=school.monthSpawned,arrived=Math.min(spawned,school.monthArrived),good=Math.min(arrived,school.monthGood),factor={优:1,良:.9,一般:.6,差:.2,待评价:.6}[cityService(c).rating]??.6,activeDays=Math.max(0,Math.min(30,boundary-school.built));let subsidy=schoolActive(c)&&spawned&&arrived?10*Math.round((c.size===2?180:120)*(activeDays/30)*(arrived/spawned)*(good/arrived)*factor):0;school.lastSubsidy=subsidy;school.monthSpawned=school.monthArrived=school.monthGood=0;education+=subsidy;if(subsidy)credit(subsidy,'education',c.name+'教育服务补贴');}m.months.unshift({month:boundary/30,bill,paid,education,debt:m.debt});m.months=m.months.slice(0,12);m.accrued=0;toast('月底结算：维护费 ¥'+bill+' · 教育补贴 ¥'+education+(m.debt?' · 待缴 ¥'+m.debt:''));save();}
function updateCityEconomy(){let m=S.maintenance;while(m.lastDay<Math.floor(S.day)){m.lastDay++;m.accrued+=maintenanceAssets().reduce((n,a)=>n+a.monthly,0)/30;if(typeof beginRatingBatch==='function')beginRatingBatch();try{for(let c of realCities())if(!c.dormant)evaluateCity(c,m.lastDay);}finally{if(typeof ratingPassengers!=='undefined')ratingPassengers=null;}if(m.lastDay%30===0)settleMonth(m.lastDay);}updateSchools();}
const world03=updateWorld;updateWorld=function(dt,oldDay){world03(dt,oldDay);updateCityEconomy();};
function serviceDistance(l,v,index,dir){let sum=0;for(let i=index;i>=0&&i<l.stops.length;i+=dir){if(serves(v,l,i))return sum;let j=i+dir;if(j<0||j>=l.stops.length)return sum;let a=S.cities[l.stops[i]],b=S.cities[l.stops[j]];sum+=Math.hypot(a.x-b.x,a.y-b.y);}return sum;}
function trainSpeedFactor(v,l,a,b,t=v.t){if(!isTrain(v.type))return 1;let len=Math.hypot(a.x-b.x,a.y-b.y),from=serviceDistance(l,v,v.index,-v.dir)+t*len,to=serviceDistance(l,v,v.index+v.dir,v.dir)+(1-t)*len,zone=v.type==='rail'?140:75;return Math.min(1,Math.sqrt(.28*.28+Math.min(from,to)/zone));}
function advanceVehicleProgress(v,l,a,b,dt){let base=Math.max(.2,edgeTime(a,b,l.type)),t=v.t;for(let remaining=dt;remaining>0&&t<1;){let h=Math.min(.025,remaining);t+=h/base*trainSpeedFactor(v,l,a,b,t);remaining-=h;}return t;}
function showCityEconomy(id){let c=S.cities[id],svc=cityService(c),s=c.school;openModal(`<div class="modal-head"><div><span class="eyebrow">CITY SERVICES / 0.4</span><h2>${escapeHTML(c.name)} · 城市服务</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="finance-summary"><span>服务评价<b>${svc.rating}${svc.score===null?'':' · '+svc.score}</b></span><span>近14日送达率<b>${Math.round((svc.delivery??1)*100)}%</b></span><span>平均累计候车<b>${Math.round(svc.wait||0)}秒</b></span><span>拥挤天数占比<b>${Math.round((svc.congestion||0)*100)}%</b></span></div><p>${escapeHTML(svc.reason)}。有效样本 ${svc.count||0} 人；连续差评 ${svc.badDays}/30天。${S.day<svc.protectUntil?'保护期剩余 '+Math.ceil(svc.protectUntil-S.day)+'天。':''}</p><p>50%送达率＋30%候车＋20%拥挤。生成满1天的出行才纳入送达率；至少6人后评价，送达率不足35%直接评差。差评15天预警、30天降一级，降级后保护15天；连续15天优/良可恢复曾达到的等级，不重复发奖。</p><section class="infra-card"><h3>▤ ${s?'城市学校':'学校建设'}</h3>${s?`<p>${schoolActive(c)?'招生运营中':'城市规模不足，暂停招生与补贴'}<br>本月学生出发 ${s.monthSpawned} · 到校 ${s.monthArrived} · 候车合格 ${s.monthGood}<br>上月教育补贴 ¥${s.lastSubsidy}。学生到校后产生返程需求。</p>`:`<p>小城及大城市可建，每城1所，建设费 ¥${SCHOOL_COST}。学生票款＋按服务表现结算的月底教育补贴。</p><button onclick="buildSchool(${id})" ${c.dormant||c.size<1?'disabled':''}>${c.size<1?'城市成长为小城后开放':'建设学校 ¥'+SCHOOL_COST}</button>`}</section><a href="../updates/">查看0.2—0.4更新说明</a>`);}
const details03=showDetails;showDetails=function(rebuild=true){details03(rebuild);if(selected?.type==='city'){let c=S.cities[selected.id];if(c?.kind!=='bridgehead'&&!$('details').innerHTML.includes('showCityEconomy('))$('details').innerHTML+=`<div class="city-mission"><b>城市服务 · ${cityService(c).rating}</b><p>${c.school?'▤ 已建学校 · '+(schoolActive(c)?'招生中':'暂停招生'):'学校：小城及大城市开放'}</p><button onclick="showCityEconomy(${c.id})">服务评价 / 学校建设</button></div>`;}};
function showCityServices(){openModal(`<div class="modal-head"><h2>城市服务与学校</h2><button class="close" onclick="closeModal()">×</button></div><div class="task-cities">${realCities().map(c=>`<section><h3>${escapeHTML(c.name)}</h3><p>${LEVELS[c.size]} · ${cityService(c).rating}${c.school?' · ▤ 学校':''}<br>${escapeHTML(cityService(c).reason)}</p><button onclick="showCityEconomy(${c.id})">查看服务 / 建校</button></section>`).join('')}</div>`);}
function serviceTravelTime(v,l,index,dir){let a=S.cities[l.stops[index]],b=S.cities[l.stops[index+dir]],time=edgeTime(a,b,l.type);if(!isTrain(l.type))return time;let sample={...v,index,dir},sum=0;for(let i=0;i<12;i++)sum+=1/trainSpeedFactor(sample,l,a,b,(i+.5)/12);return time*sum/12;}
const operations03=showOperations;showOperations=function(){operations03();$('modal-content').innerHTML+=`<div class="tabs"><button onclick="showCityServices()">城市服务 / 学校</button><button onclick="showMaintenance()">月底维护费</button><a href="../updates/">版本更新说明</a></div>`;};
const commit03City=commitDraft;commitDraft=function(skip=false){let dormant=realCities().filter(c=>c.dormant).map(c=>c.id);commit03City(skip);if(!draft)for(let id of dormant){let c=S.cities[id];if(!c.dormant)cityService(c).protectUntil=Math.max(cityService(c).protectUntil,S.day+14);}save();};
function unusedRoad(k){return !S.lines.some(l=>l.stops.some((b,i)=>i&&key(S.cities[l.stops[i-1]],S.cities[b],l.type)===k))&&!S.vehicles.some(v=>currentEdge(v)===k);}
function removeUnusedRoad(k){if(!S.infrastructure[k]||!unusedRoad(k)||S.infrastructure[k].until>S.day)return;delete S.infrastructure[k];delete S.corridors[k];delete S.blockages[k];save();showMaintenance();}
function showMaintenance(){let m=S.maintenance;openModal(`<div class="modal-head"><h2>道路维护 · 月底结算</h2><button class="close" onclick="closeModal()">×</button></div><div class="finance-summary"><span>本月累计<b>¥${m.accrued.toFixed(1)}</b></span><span>预计月底<b>¥${maintenanceForecast().toFixed(1)}</b></span><span>待缴维护费<b>¥${m.debt.toFixed(1)}</b></span></div><p>按每天保留的设施计费，月底扣款；多线共用只算一次，动车和高铁共轨也只算一次。公路每地图单位0.25/月，普通铁路0.45、高速铁路0.65；道路每级增加12%，隧道每处另加50/月。桥梁每月（60＋长度×0.3）×（1＋桥面等级×0.15）。不足部分留作欠费，后续收入自动补缴，不断路。</p>${maintenanceAssets().map(a=>`<div class="quote-row"><span>${escapeHTML(a.label)}${a.key.startsWith('bridge-')?'':unusedRoad(a.key)?' · 闲置':''}</span><b>¥${a.monthly.toFixed(1)}/月</b>${!a.key.startsWith('bridge-')&&unusedRoad(a.key)?`<button onclick="removeUnusedRoad('${a.key}')" ${S.infrastructure[a.key].until>S.day?'disabled':''}>拆除 · 回收¥${((S.infrastructure[a.key].investment||0)*.5).toFixed(2)}</button>`:''}</div>`).join('')||'<p>还没有需要维护的设施。</p>'}<h3>月度结算记录</h3>${m.months.map(r=>`<p>第${r.month}月：维护 ¥${r.bill} · 教育补贴 ¥${r.education} · 结算后待缴 ¥${r.debt.toFixed(1)}</p>`).join('')||'<p>首月尚未结算。</p>'}`);}
const finance03=showFinance;showFinance=function(){finance03();$('modal-content').innerHTML+=`<div class="finance-summary"><span>教育补贴<b>+${S.ledger.education}</b></span><span>维护费已缴<b>−${S.ledger.maintenance}</b></span><span>预计月底维护<b>¥${maintenanceForecast().toFixed(1)}</b></span></div><button onclick="showMaintenance()">维护明细 / 拆除闲置道路</button>`;};
const ui03=updateUI;updateUI=function(){ui03();if(S.maintenance){$('maintenance-estimate').textContent='月底维护 ≈¥'+maintenanceForecast().toFixed(1);$('points').title='本月预计维护 ¥'+maintenanceForecast().toFixed(1)+' · 待缴 ¥'+S.maintenance.debt.toFixed(1);}};
function drawCityEconomy(){for(let c of realCities()){if(c.dormant)continue;let svc=cityService(c);if(c.school){let x=c.x-43,y=c.y+15;roundBody(x-13,y-11,26,22,3,'#f5f4e7','#8daca8',.9);text('▤',x,y+3,17,schoolActive(c)?'#507d87':'#a8aaa0');}if(svc.badDays>=15)text('衰退预警 '+svc.badDays+'/30',c.x,c.y+radius(c)+48,9,'#b66c4c');}}
const welcome03=welcome;welcome=function(hasSave){welcome03(hasSave);$('modal-content').innerHTML+=`<section class="infra-card"><b>0.4 · 城市服务与月度经营</b><p>中大城市可建学校，学生通勤带来票款与月底补贴。长期差评会导致城市降级；道路月底维护，账本可提前查看。动车、高铁进出实际停靠站时平滑加减速，快车通过站与桥头不额外减速。</p><button onclick="showCityServices()">查看城市服务</button> <a href="../updates/">0.2—0.4 更新说明</a></section>`;};
const help03=help;help=function(){help03();$('modal-content').innerHTML+=`<p>0.4：运营中心→城市服务/学校；收支账本→月底维护。小城起可建学校，工作日产生学生，书本标记指定城市。服务评价15天差评预警、30天降级，改善后可恢复；样本不足与保护期不处罚。公交路段内匀速，动车/高铁在实际停靠站间加减速。</p><a href="../updates/">完整更新说明</a>`;};
function shopTrainCarsHTML(){let trains=S.vehicles.filter(v=>isTrain(v.type)&&!v.retired&&!v.recall&&S.lines.some(l=>l.id===v.line&&!l.retiring)).sort((a,b)=>(a.type==='emu'?0:1)-(b.type==='emu'?0:1)||a.id-b.id);return `<section class="car-shop"><span class="eyebrow">TRAIN CAPACITY</span><h3>动车 / 高铁 · 增加车厢</h3><p>为指定列车增加1节车厢，立即增加载客量。初始2节，最多8节；动车首节¥700、高铁首节¥1100，之后每次加价¥200。</p><div class="car-shop-grid">${trains.map(v=>{let line=S.lines.find(l=>l.id===v.line),full=v.cars>=8,price=carPrice(v);return `<article class="infra-card"><div class="mission-heading"><b>${TYPES[v.type].name} #${v.id}</b><small>${v.cars}/8节</small></div><p>${escapeHTML(line.name)}<br>当前容量 ${vehCap(v)}人${full?'':` → ${vehCap({...v,cars:v.cars+1})}人`}</p><button onclick="purchaseTrainCar(${v.id},${v.cars})" ${full||S.points<price?'disabled':''}>${full?'已达8节上限':`＋1节车厢 · ¥${price}${S.points<price?' · 资金不足':''}`}</button></article>`;}).join('')||'<div class="infra-card"><b>暂无可扩容列车</b><p>先购买动车或高铁并投入线路，再回到商店选择具体列车加车厢。</p></div>'}</div></section>`;}
const shop04BeforeCars=shop;shop=function(){shop04BeforeCars();$('modal-content').innerHTML+=shopTrainCarsHTML();};
function purchaseTrainCar(id,expectedCars){let v=S.vehicles.find(v=>v.id===id),line=v&&S.lines.find(l=>l.id===v.line);if(!v||!isTrain(v.type)||v.retired||v.recall||!line||line.retiring||v.cars!==expectedCars||v.cars>=8)return;let price=carPrice(v);if(S.points<price){toast('资金不足，需要 ¥'+price);shop();return;}upgradeCar(id);updateUI();shop();toast(TYPES[v.type].name+' #'+id+' 已增加1节车厢 · '+v.cars+'/8节 · 容量'+vehCap(v)+'人');}
$('operations').onclick=()=>showOperations();$('finance').onclick=()=>showFinance();$('help').onclick=()=>help();
// School maintenance training and regional repair centres, compatible with existing 0.4 saves.
const REPAIR_CENTER_COST=5000,REPAIR_CENTER_RADIUS=300;
let repairCenterPreview=null;
function schoolMaintenanceEligible(c){return c&&schoolActive(c)&&['优','良'].includes(cityService(c).rating);}
function bridgeSchoolCities(bridge){let heads=new Set(bridge.heads),cities=new Set(),visited=new Set(),pending=[...heads];while(pending.length){let id=pending.shift();if(visited.has(id))continue;visited.add(id);for(let x of Object.values(S.infrastructure)){if(x.type!==bridge.type||x.a!==id&&x.b!==id)continue;let other=S.cities[x.a===id?x.b:x.a];if(!other||other.removed)continue;if(other.kind==='bridgehead'){if(!heads.has(other.id))pending.push(other.id);}else cities.add(other.id);}}return [...cities].map(id=>S.cities[id]);}
function assetSchoolCities(asset){if(asset.key.startsWith('bridge-')){let bridge=S.bridges.find(b=>b.id===Number(asset.key.slice(7)));return bridge?bridgeSchoolCities(bridge):[];}let infra=S.infrastructure[asset.key];return infra?[S.cities[infra.a],S.cities[infra.b]].filter(c=>c?.kind!=='bridgehead'):[];}
const maintenanceAssetsBeforeSchool=maintenanceAssets;maintenanceAssets=function(){return maintenanceAssetsBeforeSchool().map(asset=>{let schools=assetSchoolCities(asset).filter(schoolMaintenanceEligible);if(!schools.length)return {...asset,baseMonthly:asset.monthly,schoolDiscount:0,saved:0};let monthly=10*Math.round(asset.monthly/10*.9*100)/100;return {...asset,baseMonthly:asset.monthly,monthly,schoolDiscount:.1,saved:Math.round((asset.monthly-monthly)*100)/100,schools:schools.map(c=>c.id)};});};
function activeRepairCenters(){return realCities().filter(c=>c.repairCenter&&!c.dormant);}
function repairCoverage(a,b){let dx=b.x-a.x,dy=b.y-a.y,len2=dx*dx+dy*dy,centers=activeRepairCenters();if(!len2)return centers.some(c=>Math.hypot(c.x-a.x,c.y-a.y)<=REPAIR_CENTER_RADIUS)?1:0;let spans=[];for(let c of centers){let fx=a.x-c.x,fy=a.y-c.y,B=2*(fx*dx+fy*dy),C=fx*fx+fy*fy-REPAIR_CENTER_RADIUS**2,disc=B*B-4*len2*C;if(disc<=0)continue;let root=Math.sqrt(disc),lo=Math.max(0,(-B-root)/(2*len2)),hi=Math.min(1,(-B+root)/(2*len2));if(hi>lo)spans.push([lo,hi]);}spans.sort((x,y)=>x[0]-y[0]);let total=0,end=0;for(let [lo,hi] of spans){total+=Math.max(0,hi-Math.max(end,lo));end=Math.max(end,hi);}return Math.min(1,total);}
function repairAdjustedQuote(q,a,b){if(!q||!a||!b)return q;let coverage=repairCoverage(a,b);return {...q,baseDays:q.days,coverage,days:Math.round(q.days*(1-.1*coverage)*100)/100};}
const upgradeQuoteBeforeCenter=upgradeQuote;upgradeQuote=function(k){let x=S.infrastructure[k];return repairAdjustedQuote(upgradeQuoteBeforeCenter(k),S.cities[x?.a],S.cities[x?.b]);};
const bridgeQuoteBeforeCenter=bridgeUpgradeQuote;bridgeUpgradeQuote=function(x){return repairAdjustedQuote(bridgeQuoteBeforeCenter(x),S.cities[x.heads[0]],S.cities[x.heads[1]]);};
const repairQuoteBeforeCenter=repairQuote;repairQuote=function(k){let ids=k.split('-').slice(-2).map(Number);return repairAdjustedQuote(repairQuoteBeforeCenter(k),S.cities[ids[0]],S.cities[ids[1]]);};
function repairCenterHTML(c){let built=!!c.repairCenter,eligible=!c.dormant&&c.size>=1;return `<section class="infra-card"><h3>⚒ 检修中心</h3><p>${built?'已建成 · 区域工程支援':'小城及大城市可建，每城1座 · 建设费 ¥'+REPAIR_CENTER_COST}<br>覆盖半径${REPAIR_CENTER_RADIUS}，完全覆盖路段的新开工项目工期−10%。部分覆盖按长度折算，重叠不重复加速。支持道路升级、铁路改造、桥面拓宽和灾后抢修。</p>${built?`<button onclick="previewRepairCenter(${c.id})">查看覆盖范围</button>`:`<button onclick="buildRepairCenter(${c.id})" ${eligible?'':'disabled'}>${eligible?'建设检修中心 ¥'+REPAIR_CENTER_COST:'城市成长为小城后开放'}</button> <button onclick="previewRepairCenter(${c.id})" ${eligible?'':'disabled'}>预览范围</button>`}</section>`;}
function buildRepairCenter(id){let c=S.cities[id];if(!c||c.kind==='bridgehead'||c.dormant||c.size<1||c.repairCenter)return toast('小城及大城市每城可建一座检修中心');selected={type:'city',id};openModal(`<div class="modal-head"><h2>${escapeHTML(c.name)} · 检修中心</h2><button class="close" onclick="closeModal()">×</button></div><p>费用 ¥${REPAIR_CENTER_COST}，覆盖半径${REPAIR_CENTER_RADIUS}。完全覆盖的新开工升级与抢修工期减少10%；跨范围路段按覆盖长度折算，多个中心按联合覆盖计算，不叠加加速。</p><p>建设费和维修费不打折；正在施工的项目保持原工期。建设后永久保留。</p><div class="construction-actions"><button onclick="previewRepairCenter(${id})">地图预览</button><button class="primary" onclick="confirmRepairCenter(${id})" ${S.points<REPAIR_CENTER_COST?'disabled':''}>支付 ¥${REPAIR_CENTER_COST} 建设</button></div>`);}
function confirmRepairCenter(id){let c=S.cities[id];if(!c||c.kind==='bridgehead'||c.dormant||c.size<1||c.repairCenter||S.points<REPAIR_CENTER_COST)return;spend(REPAIR_CENTER_COST,'construction',c.name+'检修中心建设');c.repairCenter={built:S.day};repairCenterPreview=null;save();updateUI();closeModal();openCity(id);toast('检修中心建成 · 覆盖区域新开工项目工期缩短');}
function previewRepairCenter(id){let c=S.cities[id];if(!c||c.kind==='bridgehead'||c.dormant||!c.repairCenter&&c.size<1)return;repairCenterPreview={id};closeModal();openCity(id);toast('检修中心半径300 · 细虚线为覆盖范围'+(c.repairCenter?'':'，点击城市检修中心可确认建设'));}
const drawEconomyBeforeCenter=drawCityEconomy;drawCityEconomy=function(){drawEconomyBeforeCenter();for(let c of realCities()){if(!c.repairCenter||c.dormant)continue;let x=c.x+43,y=c.y+15;roundBody(x-13,y-11,26,22,3,'#f5eee0','#b19b73',.9);text('⚒',x,y+3,15,'#9b8054');}let id=repairCenterPreview?.id??(selected?.type==='city'&&S.cities[selected.id]?.repairCenter?selected.id:null);if(id===null)return;let c=S.cities[id];if(!c||c.dormant)return;ctx.save();ctx.strokeStyle='#a98d5a99';ctx.lineWidth=1/Math.max(.5,view.scale);ctx.setLineDash([6/view.scale,7/view.scale]);ctx.beginPath();ctx.arc(c.x,c.y,REPAIR_CENTER_RADIUS,0,Math.PI*2);ctx.stroke();text((c.repairCenter?'检修覆盖':'检修选址预览')+' · 300',c.x,c.y-REPAIR_CENTER_RADIUS+16,10,'#a18759');ctx.restore();};
const clearSelectionBeforeCenter=clearSelection;clearSelection=function(){repairCenterPreview=null;clearSelectionBeforeCenter();};
const resetBeforeCenter=reset;reset=function(){repairCenterPreview=null;resetBeforeCenter();};
const cityEconomyBeforeCenter=showCityEconomy;showCityEconomy=function(id){cityEconomyBeforeCenter(id);let c=S.cities[id],saving=maintenanceAssets().filter(a=>a.schools?.includes(id)).reduce((n,a)=>n+a.saved,0);$('modal-content').innerHTML+=`<section class="infra-card"><b>学校 · 技术人才培养</b><p>${schoolMaintenanceEligible(c)?'维护减免生效：直接连接本城的道路、铁路、桥隧维护费−10%。':c.school?'维护减免未生效：学校需正常运营且城市评价达到优或良。':'建校后正常运营且城市评价达到优或良，可减免连接本城设施的维护费10%。'}<br>当前优惠设施预计每月合计少支出 ¥${saving.toFixed(1)}；两端学校不叠加，共用设施不重复优惠。接桥的两岸城市按已建接入道路判断。</p></section>`+repairCenterHTML(c);};
const engineeringBeforeCenter=showEngineering;showEngineering=function(){engineeringBeforeCenter();$('modal-content').innerHTML+=`<h3>城市检修中心</h3><div class="task-cities">${realCities().filter(c=>!c.dormant).map(c=>`<section><b>${escapeHTML(c.name)}</b><p>${c.repairCenter?'已建检修中心 · 半径300':c.size>=1?'可建 · ¥5000':'小城后开放'}<br>新开工升级与抢修最多缩短10%</p><button onclick="${c.repairCenter?'previewRepairCenter':'buildRepairCenter'}(${c.id})" ${!c.repairCenter&&c.size<1?'disabled':''}>${c.repairCenter?'查看范围':'建设检修中心'}</button></section>`).join('')}</div>`;};
const detailsBeforeCenter=showDetails;showDetails=function(rebuild=true){detailsBeforeCenter(rebuild);if(selected?.type==='city'){let c=S.cities[selected.id];if(c?.kind!=='bridgehead'&&!$('details').innerHTML.includes('buildRepairCenter('))$('details').innerHTML+=`<div class="detail-actions"><button onclick="buildRepairCenter(${c.id})" ${c.repairCenter||c.dormant||c.size<1?'disabled':''}>${c.repairCenter?'已建检修中心':'检修中心 ¥5000'}</button>${c.repairCenter?`<button onclick="previewRepairCenter(${c.id})">检修覆盖范围</button>`:''}</div>`;}};
const maintenanceBeforeCenter=showMaintenance;showMaintenance=function(){maintenanceBeforeCenter();let assets=maintenanceAssets(),saving=assets.reduce((n,a)=>n+a.saved,0);$('modal-content').innerHTML+=`<section class="infra-card"><b>学校维护减免 · 按当前状态预计少支出 ¥${saving.toFixed(1)}/月</b><p>学校正常运营且城市评价为优或良时，连接该城的设施维护费减免10%；两端学校、共用线路不叠加。上方设施价格和月底预计已包含优惠。减免逐日累计，不追溯此前费用。</p>${assets.filter(a=>a.schoolDiscount).map(a=>`<div class="quote-row"><span>${escapeHTML(a.label)} · 学校−10%</span><b>¥${a.baseMonthly.toFixed(2)} → ¥${a.monthly.toFixed(2)}/月</b></div>`).join('')||'<p>当前暂无满足条件的学校优惠。</p>'}</section>`;};
const schoolBuildBeforeCenter=buildSchool;buildSchool=function(id){let c=S.cities[id];if(!c||c.kind==='bridgehead'||c.dormant||c.size<1||c.school)return schoolBuildBeforeCenter(id);schoolBuildBeforeCenter(id);$('modal-content').innerHTML+='<p>新增技术人才培养：学校正常运营且城市评价为优或良时，连接本城设施的维护费−10%，两端学校不叠加。</p>';};
const roadInfoBeforeCenter=openInfrastructure;openInfrastructure=function(id){roadInfoBeforeCenter(id);$('modal-content').innerHTML+='<p>检修中心覆盖的新开工项目工期已按覆盖长度折算：完全覆盖−10%，重叠不叠加。</p>';};
$('engineering').onclick=()=>showEngineering();

// Complete destination arrivals before forced unloading, and recover queues from older saves.
function finishPassengerAtCity(p,city){if(!p||!city||city.kind==='bridgehead'||!matchesDestination(city,p))return false;if(p.arrivalSettled)return true;p.arrivalSettled=true;S.delivered++;S.periodDelivered++;city.served=(city.served||0)+1;completeTrip(p,city);return true;}
function settleDestinationQueues(){let count=0;for(let city of realCities()){if(city.dormant||!city.q.length)continue;let pending=city.q;city.q=[];for(let p of pending){if(finishPassengerAtCity(p,city))count++;else city.q.push(p);}}return count;}
const tickBeforeArrivalFix=tick;tick=function(dt){settleDestinationQueues();tickBeforeArrivalFix(dt);};
const loadBeforeArrivalFix=load;load=function(){let ok=loadBeforeArrivalFix();if(ok&&settleDestinationQueues())save();return ok;};
resize();const hadSave=load();if(!hadSave)reset();updateUI();welcome(hadSave);/* The loop starts once every script layer has run (later layers redefine render helpers), and one failing frame
   never stops it: the next frame is scheduled before the error propagates. */
{const frameRaw=frame;frame=function(t){try{return frameRaw(t);}catch(e){if(typeof requestAnimationFrame==="function"){if(typeof cancelAnimationFrame==="function")cancelAnimationFrame(drawFrame);drawFrame=requestAnimationFrame(frame);}throw e;}};}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{drawFrame=requestAnimationFrame(frame);},{once:true});else requestAnimationFrame(frame);
/* Top notice: closable; hints stay closed for good, live events stay closed until they end. */
(function(){const KEY='transit04-notice-off',PERM={intro:1,dormant:1};let off={},session={},cur='';try{off=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
const cat=t=>t.startsWith('城市成长测试版')?'intro':t.startsWith('发现待接入')?'dormant':t.startsWith('♪')?'concert':t.startsWith('道路施工')?'construction':t.startsWith('受损')?'blockage':t.startsWith('区域')?'weather':t.slice(0,6);
const base=updateUI;updateUI=function(){base();let el=$('notice');if(!el)return;let t=el.textContent||'';cur=t?cat(t):'';for(const k in session)if(k!==cur)delete session[k];if(cur&&(off[cur]||session[cur]))el.textContent='';};
let btn=typeof document!=='undefined'&&document.getElementById?.('notice-close');if(btn)btn.onclick=()=>{if(!cur)return;if(PERM[cur]){off[cur]=1;try{localStorage.setItem(KEY,JSON.stringify(off))}catch{}}else session[cur]=1;$('notice').textContent='';};})();
